def transform(grid):
    # Extend any diagonal run of two or more matching non-background cells
    # in the same direction to the grid edge.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1), (-1, -1), (-1, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    rr, cc = r, c
                    while 0 <= rr - dr < h and 0 <= cc - dc < w and grid[rr-dr][cc-dc] == color:
